-- Literal dialogue/hand-ins only; full-chain limitations: docs/coldain-quest-chains.md.
local item_lib = require("items")

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 1415, item2 = 1425 }) then
    e.self:Say("Well I'll be derned. An outlander that can make a good Bearmeat 'n Bread! Thank ye, " .. e.other:GetCleanName() .. ".")
    e.other:SummonItem(1419)
    e.other:AddEXP(50000)
    e.other:Faction(406, 10, 0)
    e.other:Faction(405, 10, 0)
    e.other:Faction(419, -30, 0)
    e.other:Faction(448, -30, 0)
  elseif item_lib.check_turn_in(e.trade, { item1 = 1425 }) then
    e.self:Say("Well I'll be derned. An outlander that can make a good Bearmeat 'n Bread! Thank ye, " .. e.other:GetCleanName() .. ".")
    e.other:AddEXP(5000)
    e.other:Faction(406, 10, 0)
    e.other:Faction(405, 10, 0)
    e.other:Faction(419, -30, 0)
    e.other:Faction(448, -30, 0)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
